import React, { useState, useEffect } from 'react';

import { getAllPositions } from '@apps/Hiking/@services/hikingPositionsAndVacancies.service';
import { IHikingPositionFull } from '@apps/Hiking/@types/hikingPositionsAndVacancies.types';
import PageLoader from '@components/PageLoader';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

function AllPositions() {
  const [positions, setPositions] = useState<IHikingPositionFull[] | null>(null);

  useEffect(() => {
    const fetch = async () => {
      const allPositions = await getAllPositions();
      setPositions(allPositions);
    };
    fetch();
  }, []);

  if (positions == null) {
    return <PageLoader />;
  }

  return (
    <PohContainer>
      <h2>Должности в походах</h2>
      {!positions?.length && <Empty>Нет позиций</Empty>}
      {positions.map((pos) => (
        <section key={pos.id} className="mb-5">
          <h3>{pos.name}</h3>
          <p>{pos.description}</p>
          <PohRow>
            <PohCol sm={4}>
              <h5>До похода</h5>
              <div dangerouslySetInnerHTML={{ __html: pos.desc_before }} />
            </PohCol>
            <PohCol sm={4}>
              <h5>Во время похода</h5>
              <div dangerouslySetInnerHTML={{ __html: pos.desc_during }} />
            </PohCol>
            <PohCol sm={4}>
              <h5>После похода</h5>
              <div dangerouslySetInnerHTML={{ __html: pos.desc_after }} />
            </PohCol>
          </PohRow>
        </section>
      ))}
    </PohContainer>
  );
}

export default AllPositions;
